import {getAction,getCharacter} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const wishPhysicalScenarios=['wish-one-hand','wish-two-hand','wish-one-own-hand','wish-two-own-hand','wish-one-deck','wish-two-deck','wish-one-attachment','wish-two-attachment','wish-one-chant','wish-two-chant','wish-one-blood','wish-two-blood','wish-one-blessing','wish-two-blessing','wish-one-haja','wish-two-haja','wish-one-dawn','wish-two-dawn','wish-one-fusen','wish-two-fusen','wish-one-deck-dawn','wish-two-deck-dawn','wish-one-own-follower','wish-two-own-follower','wish-one-otherworld','wish-two-otherworld','wish-one-discard','wish-two-discard','wish-one-mother','wish-two-mother','wish-one-fate','wish-two-fate','wish-one-decline','wish-two-decline'] as const;
export type WishPhysicalScenario=typeof wishPhysicalScenarios[number];
export function isWishPhysicalScenario(name:string):name is WishPhysicalScenario{return (wishPhysicalScenarios as readonly string[]).includes(name);}
export function wishMode(name:WishPhysicalScenario){const mode=name.split('-').slice(2).join('-'),desired=({attachment:'a2-p03-r3c1',chant:'a2-p13-r1c1',blood:'a2-p01-r1c3',blessing:'a2-p01-r2c1',haja:'a2-p01-r2c2',dawn:'a2-p01-r1c2',fusen:'a2-p01-r1c1','deck-dawn':'a2-p01-r1c2','own-follower':'a2-p18-r3c3',mother:'a2-p05-r1c2'} as Record<string,string>)[mode];return {mode,desired,card:name.startsWith('wish-one-')?'a2-p04-r3c2' as const:'a2-p04-r3c3' as const,open:['blood','blessing','haja','dawn','fusen'].includes(mode),capacity:mode==='blessing'||mode==='haja',deck:['deck','deck-dawn','otherworld','discard'].includes(mode),hand:mode==='hand'||mode==='own-hand'};}
/** All persistent zones and prior deaths/otherworld presence are real transitions.
 * Only starting inventory, stats and deck order are arranged. */
export function makeWishPhysicalScenario(name:WishPhysicalScenario,players:{id:string;name:string}[],beforeStart=false){
 const m=wishMode(name),priorB=['attachment','chant','haja','discard'].includes(m.mode),priorD=['dawn','fusen','deck-dawn','otherworld'].includes(m.mode);let s=createGame(players,entropy(),{startingSeat:priorB?1:priorD?3:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,['侍大将のシン',m.mode==='mother'?getCharacter('c2-p04-r1c2')!.name:'黒騎士ガーウィン','大神官ジル',priorD&&m.mode!=='fusen'?'白魔術師シェリム':'魔導王ガイナス'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=6-gameStats(s,p.id).spirit;}if(m.mode==='fusen')s.players[c]!.permanent!.endurance!+=4-gameStats(s,c).endurance;
 const setupOpen=m.open?m.desired:m.mode==='otherworld'?'a2-p01-r1c3':undefined;const keep=[takeCard(s,a,m.card),takeCard(s,d,'a2-p02-r2c3')],bFollowers=m.mode==='blessing'?['a2-p18-r3c3','a2-p21-r2c2','a2-p21-r2c1']:m.open||m.mode==='otherworld'?['a2-p18-r3c3']:[],aFollowers=m.mode==='own-follower'?['a2-p18-r3c3']:[];for(const id of bFollowers)keep.push(takeCard(s,b,id));for(const id of aFollowers)keep.push(takeCard(s,a,id));if(m.mode==='attachment')keep.push(takeCard(s,b,m.desired!));if(m.mode==='chant'||m.mode==='haja')keep.push(takeCard(s,b,'a2-p13-r1c1'));if(m.mode==='haja')keep.push(takeCard(s,b,'a2-p14-r2c2'));if(m.mode==='mother')keep.push(takeCard(s,a,m.desired!));if(m.mode==='discard')keep.push(takeCard(s,b,'a2-p24-r1c2'));if(priorD)keep.push(takeCard(s,d,m.mode==='fusen'?'a2-p24-r1c2':'a2-p14-r2c2'));for(const p of players)trimHand(s,p.id,...keep);
 // Reserve both same-name potions and any acquired OPEN away from prior hand refills.
 for(const id of ['a2-p04-r2c3','a2-p04-r3c1',...(setupOpen?[setupOpen]:m.mode==='deck-dawn'?[m.desired!]:[])]){takeCard(s,c,id);s.players[c]!.hand=s.players[c]!.hand.filter(x=>x!==id);s.deck.push(id);}s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(setupOpen){s.deck=s.deck.filter(id=>id!==setupOpen);s.deck.unshift(setupOpen);}s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`WISH_PHYSICAL_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('WISH_PHYSICAL_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('WISH_PHYSICAL_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<500;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('WISH_PHYSICAL_FIXTURE_WINDOW');}
 function start(id:string){act(id,{type:'START_TURN'});settle();if(s.phase==='draw'){act(id,{type:'CHOOSE_DRAW',draw:false});settle();}}
 function end(id:string){if(s.phase==='action')act(id,{type:'PASS_ACTION'});if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>!keep.includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});settle();}
 for(const id of [a,b,c,d]){for(const cardInstanceId of (id===a?aFollowers:id===b?bFollowers:[]).slice(0,2))act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});act(id,{type:'PASS_SETUP'});}
 // The blessing arrives with the round-end refill, so the third follower goes down in the next round (G10).
 for(const cardInstanceId of bFollowers.slice(2))act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(beforeStart)return s;
 if(priorB){start(b);if(m.mode==='attachment')act(b,{type:'PLAY_TURN_CARD',cardInstanceIds:[m.desired!]});else if(m.mode==='discard')act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[c],dedicated:false});else act(b,{type:'CHANT',cardInstanceId:'a2-p13-r1c1'});settle();end(b);for(const id of [c,d]){start(id);end(id);}if(m.mode==='haja'){start(a);end(a);start(b);act(b,{type:'CHANT',cardInstanceId:'a2-p14-r2c2'});settle();end(b);for(const id of [c,d]){start(id);end(id);}}}
 if(priorD){start(d);if(m.mode!=='fusen'){act(d,{type:'CHANT',cardInstanceId:'a2-p14-r2c2'});settle();end(d);for(const id of [a,b,c]){start(id);end(id);}start(d);}act(d,{type:'ATTACK',cardInstanceId:m.mode==='fusen'?'a2-p24-r1c2':'a2-p14-r2c2',targetIds:[m.mode==='otherworld'?b:c],dedicated:m.mode!=='fusen'});if(m.mode!=='fusen'){for(let n=0;n<200&&s.windows?.at(-1)?.kind!=='lifetime-effect-choice';n++){const w=s.windows!.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}act(d,{type:'CHOOSE_LIFETIME_EFFECT',choice:'apply'});const first=s.windows!.at(-1)!.id;for(let n=0;n<200&&s.windows?.at(-1)?.id===first;n++){const w=s.windows!.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'},6);}settle();}else settle();const expected=m.mode==='fusen'?'dead':'otherworld';if(s.players[m.mode==='otherworld'?b:c]!.presence!==expected)throw Error('WISH_NO_ACTUAL_PRESENCE');end(d);}start(a);
 if(m.mode==='mother'){act(b,{type:'REVEAL_CHARACTER'});settle();act(a,{type:'PLAY_TURN_CARD',cardInstanceId:'a2-p05-r1c2',targetId:b,mode:'ordinary'});settle();end(a);for(const id of [b,c,d]){start(id);end(id);}start(a);}return s;
}
